import pickle
import base64
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

# 模拟用户会话存储，实际项目中可能是 Redis 或数据库
SESSION_STORE = {}

class UserProfile:
    """用户配置类，仅用于演示属性注入边界"""
    def __init__(self, username, role="guest"):
        self.username = username
        self.role = role
        self.preferences = {}

    def update_preferences(self, key, value):
        # 仅允许更新白名单内的偏好项
        allowed_keys = {"theme", "language", "timezone"}
        if key in allowed_keys:
            self.preferences[key] = value
            return True
        return False

@app.route("/api/session/save", methods=["POST"])
def save_session():
    """将用户会话序列化后存入存储（正常功能）"""
    data = request.get_json()
    username = data.get("username", "anonymous")
    profile = UserProfile(username)
    profile.preferences = data.get("preferences", {})

    # 序列化并存储
    session_blob = base64.b64encode(pickle.dumps(profile)).decode()
    session_id = os.urandom(8).hex()
    SESSION_STORE[session_id] = session_blob
    return jsonify({"session_id": session_id})

@app.route("/api/session/load", methods=["POST"])
def load_session():
    """从存储中恢复会话（存在漏洞的入口）"""
    session_id = request.json.get("session_id")
    if session_id not in SESSION_STORE:
        return jsonify({"error": "session not found"}), 404

    blob = SESSION_STORE[session_id]
    # 漏洞点：直接反序列化客户端可控的 blob，未做任何安全校验
    user_data = base64.b64decode(blob)
    profile = pickle.loads(user_data)  # line 40: 反序列化漏洞

    # 后续业务逻辑（攻击者可通过构造恶意 pickle 在此处执行任意代码）
    if profile.role == "admin":
        return jsonify({"status": "admin access granted", "user": profile.username})
    return jsonify({"status": "user access", "user": profile.username})

@app.route("/api/profile/update", methods=["POST"])
def update_profile():
    """正常属性更新接口（用于对比展示属性注入与反序列化的边界）"""
    data = request.json
    profile = UserProfile(data.get("username", "guest"))
    # 此处有属性注入风险，但通过白名单限制了
    for key, value in data.get("preferences", {}).items():
        if not profile.update_preferences(key, value):
            return jsonify({"error": f"key '{key}' not allowed"}), 400
    return jsonify({"status": "updated", "preferences": profile.preferences})

if __name__ == "__main__":
    app.run(debug=False, port=5000)

import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.SessionAttributes;

@Controller
@SessionAttributes("user")
public class UserProfileController {

    // 模拟数据库中的用户对象
    private static class User {
        private String username;
        private String email;
        private boolean admin;
        private String role;

        public String getUsername() { return username; }
        public void setUsername(String username) { this.username = username; }
        public String getEmail() { return email; }
        public void setEmail(String email) { this.email = email; }
        public boolean isAdmin() { return admin; }
        public void setAdmin(boolean admin) { this.admin = admin; }
        public String getRole() { return role; }
        public void setRole(String role) { this.role = role; }
    }

    @GetMapping("/profile")
    public String showProfile(@ModelAttribute("user") User user) {
        return "profile";
    }

    @PostMapping("/profile/update")
    public String updateProfile(@ModelAttribute User user, Model model) {
        // 仅允许用户更新自己的基本资料，不包含 admin 和 role 字段
        User existing = getCurrentUserFromDB(user.getUsername());
        existing.setEmail(user.getEmail());
        // 注意：这里只显式复制了 email，但 Spring 的 @ModelAttribute 已经将
        // HTTP 参数直接绑定到 user 对象上，包括 admin 和 role 字段。
        saveToDB(existing);
        model.addAttribute("user", existing);
        return "redirect:/profile";
    }

    private User getCurrentUserFromDB(String username) {
        User u = new User();
        u.setUsername(username);
        u.setEmail("existing@example.com");
        u.setAdmin(false);
        u.setRole("USER");
        return u;
    }

    private void saveToDB(User user) {
        // 模拟持久化
        System.out.println("Saving user: " + user.getUsername() +
                           ", admin=" + user.isAdmin() +
                           ", role=" + user.getRole());
    }
}

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class FileEncryptor {
    private static final String AES = "AES";
    private static final String TRANSFORMATION = "AES/CBC/PKCS5Padding";
    // 硬编码密钥（CWE-798 相关，但非本次关注点）
    private static final byte[] KEY_BYTES = "ThisIsASecretKey".getBytes(StandardCharsets.UTF_8);
    // 硬编码 IV - 所有加密操作复用同一个 IV
    private static final byte[] FIXED_IV = new byte[] {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
                                                       0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10};

    public String encryptFile(String plaintext) throws Exception {
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        SecretKeySpec keySpec = new SecretKeySpec(KEY_BYTES, AES);
        // 使用固定 IV 初始化，未使用 SecureRandom 生成随机 IV
        IvParameterSpec ivSpec = new IvParameterSpec(FIXED_IV);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);

        byte[] encrypted = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));
        return Base64.getEncoder().encodeToString(encrypted);
    }

    public String decryptFile(String encryptedBase64) throws Exception {
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        SecretKeySpec keySpec = new SecretKeySpec(KEY_BYTES, AES);
        // 解密使用相同的固定 IV（与加密一致）
        IvParameterSpec ivSpec = new IvParameterSpec(FIXED_IV);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

        byte[] decrypted = cipher.doFinal(Base64.getDecoder().decode(encryptedBase64));
        return new String(decrypted, StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws Exception {
        FileEncryptor encryptor = new FileEncryptor();
        String secretData = "user_credentials:admin:password123";
        String encrypted = encryptor.encryptFile(secretData);
        System.out.println("Encrypted: " + encrypted);
        String decrypted = encryptor.decryptFile(encrypted);
        System.out.println("Decrypted: " + decrypted);
    }
}

import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathFactory;
import java.io.StringReader;

public class UserSearchService {
    private static final String XML_DATA = "<?xml version=\"1.0\"?><users><user><id>1</id><name>alice</name><role>admin</role></user><user><id>2</id><name>bob</name><role>user</role></user><user><id>3</id><name>carol</name><role>user</role></user></users>";

    public String searchUser(String username) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new InputSource(new StringReader(XML_DATA)));

        // line 22: 用户输入直接拼接到 XPath 表达式
        String xpathExpr = "//user[name='" + username + "']/role/text()";

        XPathFactory xpathFactory = XPathFactory.newInstance();
        XPath xpath = xpathFactory.newXPath();
        XPathExpression expr = xpath.compile(xpathExpr);
        NodeList nodes = (NodeList) expr.evaluate(doc, XPathConstants.NODESET);

        if (nodes.getLength() > 0) {
            return "Role: " + nodes.item(0).getNodeValue();
        }
        return "User not found";
    }

    public static void main(String[] args) throws Exception {
        UserSearchService service = new UserSearchService();
        // 正常调用
        System.out.println(service.searchUser("bob"));
        // 恶意输入：' or '1'='1
        System.out.println(service.searchUser("' or '1'='1"));
    }
}

